+          didWeStartWork.remove();
+          unitOfWork.end();
+        }
+      }

-    } catch (Exception e) {
-      // commit transaction only if rollback didn't occur
-      if (rollbackIfNecessary(transactional, e, txn)) {
+      // everything was normal so commit the txn (do not move into try block
